const rows = [
  { first: 'Ryan', company: 'Medline Canada', address: '179 West Creek Way, Rosser, MB, R0H 1E0', reason: 'Chose Other Service', lost: '2024-12-16', proposal: true },
  { first: 'Daniel', company: 'Union Gospel Mission', address: '220 and 240 Pritchard,, Winnipeg, MB, R3B 3C7', reason: 'Lost Due to Price', lost: '2024-11-07', proposal: true },
  { first: 'Allen', company: 'Tereck Diesel', address: '1655 Dugald Road, Winnipeg, MB, R2J 0H3', reason: 'Not Interested', lost: '2025-05-29', proposal: false }
];
const F = 'font-family:Tahoma,Arial,Helvetica,sans-serif;font-size:10pt;color:#000';
const esc = s => String(s || '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const sig = '<div style="' + F + ';margin-top:16px">Kind Regards,</div>'
  + '<p style="margin:0.1pt;text-align:left"></p><p style="margin:0cm;font-size:15px;font-family:&quot;Calibri&quot;,sans-serif">Raf Lakhani <br />Brand Manager | Anago of Manitoba<br />238 St Mary’s Road | Winnipeg, MB R2H 1J3<br />t+ 204.594.4666 |Direct+ 204.809.4347 | <a href="mailto:rlakhani@anagomb.ca">rlakhani@anagomb.ca</a></p><p style="margin:0cm;font-size:15px;font-family:&quot;Calibri&quot;,sans-serif"><a href="http://www.anagomb.ca/">www.AnagoMB.ca</a></p><p></p><table><tbody><tr><td><div id="LSI_marker" style="font-size:0px"> </div></td></tr></tbody></table>';
const p = t => '<p style="' + F + ';margin:0 0 12px 0">' + t + '</p>';
return rows.map((r, i) => {
  const street = esc(String(r.address || '').split(',')[0].trim());
  const year = String(r.lost || '').slice(0, 4);
  const at = street ? ' at ' + street : '';
  const opener = r.proposal
    ? 'In ' + year + ' we put together a cleaning proposal for ' + esc(r.company) + at + '.'
    : 'In ' + year + ' we spoke about cleaning for ' + esc(r.company) + at + '.';
  let middle;
  if (/Other Service|Same Service|Canceled/.test(r.reason)) middle = 'You decided to stay with another provider at the time, and I hope it is working well. If anything has slipped, like missed areas, frequent staff changes or slow responses when something comes up, that is usually when businesses give us a second look.';
  else if (/Price/.test(r.reason)) middle = 'The price did not fit at the time. Budgets change, and so can the scope: we can adjust the frequency or focus on the high-traffic areas so the numbers work. I would be glad to rework the proposal around a budget you set.';
  else if (/In House/.test(r.reason)) middle = 'You were handling cleaning in-house at the time. If that has become more work than it is worth, we can take it off your team’s plate.';
  else middle = 'The timing was not right then, and that is completely fine. If anything has changed, like a contract coming up for renewal, a new space, or a cleaner who is not meeting expectations, I would be glad to help.';
  const offer = 'I can do a free 20-minute walkthrough and send you an updated quote within a couple of days. Just reply with a time that suits you, or call me directly at 204-809-4347.';
  const footer = '<p style="font-family:Tahoma,Arial,Helvetica,sans-serif;font-size:8pt;color:#808080;margin:12px 0 0 0">You are receiving this because you contacted Anago of Manitoba about cleaning for ' + esc(r.company) + '. Reply “unsubscribe” and I will not email you again.</p>';
  const html = p('Hi ' + esc(r.first) + ',') + p(opener + ' ' + middle) + p(offer) + sig + footer;
  return { json: { to: 'rlakhani@anagomb.ca', subject: '[SAMPLE v3 ' + (i + 1) + '/3] Quick check-in about cleaning at ' + r.company, html } };
});
